begin;

-- Generated by npm run community:reactions. Preserve existing member reactions.
on conflict (target_kind,target_id) do update set
  href=excluded.href, thread_id=excluded.thread_id, thread_title=excluded.thread_title;

-- Preserve reaction IDs while repairing the existing gallery destination.
update public.community_reaction_targets
set href = replace(href, 'item=gallery-cursed-kuzgun&', 'item=gallery-cursed-raven&')
where target_kind = 'raven' and target_id like 'gallery-cursed-kuzgun-natural-%';

commit;
